/* ###### 7.11 Error  ###### */

.main-error-wrapper {
	h1 {
		line-height: 1;
		font-size: 105px;
		font-weight: 700;
		color: #{$gray-900};
	}

	h2 {
		font-weight: 500;
		color: #{$gray-800};
		letter-spacing: -.5px;
		margin-block-end: 15px;
		margin-block-start: 20px;
	}

	h6 {
		margin-block-end: 40px;
		font-size: 14px;
	}

	.btn,
	.sp-container button {
		border-width: 2px;
		font-weight: 500;
	}
}

.sp-container .main-error-wrapper button {
	border-width: 2px;
	font-weight: 700;
}

/* ###### 7.9 Signin  ###### */

.main-card-signin {
	padding: 20px;
	display: flex;
	justify-content: space-between;
	background-color: #{$white};
	position: relative;
}

@media (max-width: 991px) {
	.main-card-signin {
		display: block !important;
		padding: 0;
	}

	.app-sidebar {
		z-index: 1029 !important;
		inset-block-start: 64px !important;
	}

	.main-nav-line-chat {
		padding: 20px !important;
	}
}

@media (min-width: 480px) {
	.main-card-signin {
		padding: 0;
		max-width: 750px;

		&.construction {
			max-width: 1000px;
		}
	}
}

.main-signin-header {
	h2 {
		font-weight: 500;
		color: #{$primary};
		letter-spacing: -1px;
	}

	h4 {
		font-weight: 500;
		color: #14112d;
		margin-block-end: 25px;
		font-size: 16px;
	}

	label {
		color: #a5a0b1;
	}

	.form-control {
		color: #14112d;
		font-weight: 500;
		border-width: 1px;
		border-color: #e3e3e3;

		&:focus {
			border-color:#{$gray-400};
			box-shadow: none;
		}

		&::placeholder {
			font-weight: 400;
			color: #a5a0b1;
		}
	}
}

.main-card-signin {
	box-shadow: none;
}

.main-signin-header {

	.btn,
	.sp-container button {
		margin-block-start: 25px;
	}
}

.sp-container .main-signin-header button {
	margin-block-start: 25px;
}

.main-signin-footer {
	p {
		color: #a5a0b1;

		&:first-child {
			margin-block-end: 5px;
		}

		&:last-child {
			margin-block-end: 0;
		}
	}

	a {
		color: #14112d;
		font-weight: 700;

		&:hover,
		&:focus {
			color: #{$primary};
		}
	}
}

/* ###### 7.10 Signup  ###### */
.main-signup-header {
	h2 {
		font-weight: 500;
		color: #{$primary} !important;
		letter-spacing: -1px;
	}

	h4 {
		font-size: 20px;
		font-weight: 400;
		color: #14112d;
		margin-block-end: 25px;
	}

	label {
		color: #212529;
	}

	.form-control {
		color: #14112d;
		font-weight: 500;
		border-width: 1px;
		border-color: #e3e3e3;

		&:focus {
			border-color:#{$gray-400};
			box-shadow: none;
		}

		&::placeholder {
			font-weight: 400;
			color: #a5a0b1;
		}
	}

	>.btn {
		margin-block-start: 25px;
	}
}

.sp-container .main-signup-header>button {
	margin-block-start: 25px;
}

.main-signup-header .row {
	margin-block-start: 20px;

	>div {

		.btn i,
		.sp-container button i {
			font-size: 15px;
			line-height: 0;
			margin-inline-end: 5px;
		}
	}
}

.sp-container .main-signup-header .row>div button i {
	font-size: 15px;
	line-height: 0;
	margin-inline-end: 5px;
}

.main-signup-header .row>div:first-child {

	.btn,
	.sp-container button {
		background-color: #19c0c0;
		color: #{$white};
	}
}

.sp-container .main-signup-header .row>div:first-child button {
	background-color: #4267b2;
	color: #{$white};
}

.main-signup-header .row>div:first-child {

	.btn:hover,
	.sp-container button:hover {
		background-color: #1bd0d0;
		color: #{$white};
	}
}

.sp-container .main-signup-header .row>div:first-child button:hover {
	background-color: #1bd0d0;
	color: #{$white};
}

.main-signup-header .row>div:first-child {

	.btn:focus,
	.sp-container button:focus {
		background-color: #1bd0d0;
		color: #{$white};
	}
}

.sp-container .main-signup-header .row>div:first-child button:focus {
	background-color: #1bd0d0;
	color: #{$white};
}

.main-signup-footer {
	p {
		color: #a5a0b1;
		margin-block-end: 0;
	}

	a {
		color: #14112d;
		font-weight: 700;

		&:hover,
		&:focus {
			color: #{$primary};
		}
	}
}

.login,
.image {
	min-height: 100vh;
}

.construction {
	.form-control {
		height: 39px;
		padding: 0.375rem 1rem;
		border-radius: 4px;
		width: 100%;
	}

	.btn.btn-icon {
		border: 0;
		text-align: center;
		padding: 0;
		background: 0 0;
		font-size: 20px;
		color: #{$black-9};
		margin: 0 5px;
		border-radius: 3px;
	}

	.input-group-prepend,
	.input-group-append {
		position: absolute;
		inset-inline-end: 0;
	}

	.input-group> {
		.input-group-append>.btn {
			border-start-start-radius: 0;
			border-start-end-radius: 4px;
			border-end-end-radius: 4px;
			border-end-start-radius: 0;
			margin: 0;
			padding: 0 25px;
			height: 38px;
			line-height: 39px;
			float: $float-end;
			border: 0;
			font-size: 14px;
			color: #{$white};
			box-shadow: none;
			position: relative;
			overflow: hidden;
			z-index: 99;
		}

		.form-control:not(:last-child),
		.custom-select:not(:last-child) {
			border-start-end-radius: 4px;
			border-end-end-radius: 4px;
		}
	}
}

@media (max-width: 991px) {
	.error-page {
		height: 70%;
		width: 70%;
	}
}

@media (min-width: 992px) {
	.main-card-signin {
		border: 0 !important;
		box-shadow: none !important;
	}

	.main-signin-header {
		box-shadow: none !important;
	}

	.error-page {
		height: 30%;
		width: 30%;
	}
}

@media (max-width: 400px) {
	.main-error-wrapper .tx-130 {
		font-size: 95px;
	}
}



.divider {
	border-block-start: 1px solid #{$border};
	position: relative;

	&::before {
		content: "";
		position: absolute;
		inset-block-start: 50%;
		inset-inline-start: 50%;
		transform: translate(-50%, -50%);
		background: #{$white};
		padding: 0px 10px;
	}

	&.or {
		&::before {
			content: "or";
		}
	}
}
.logo-dark {
	display: block;
    margin: 0 auto;
}

.logo-light {
	display: none;
    margin: 0 auto;
}
.sign-favicon-dark {
	display: block;
    margin: 0 auto;
}

.sign-favicon-light {
	display: none;
    margin: 0 auto;
}