	}
  }
  
  .tooltip {
	position: absolute;
	z-index: 0;
	display: block;
	margin: 0;
	font-family: inherit;
	font-style: normal;
	font-weight: 400;
	line-height: 1.5;
	text-align: start;
	text-align: start;
	text-decoration: none;
	text-shadow: none;
	text-transform: none;
	letter-spacing: normal;
	word-break: normal;
	word-spacing: normal;
	white-space: normal;
	line-break: auto;
	font-size: 0.76562rem;
	word-wrap: break-word;
	opacity: 0;
  
	&.show {
	  opacity: 0.9;
	}
  
	.tooltip-arrow {
	  position: absolute;
	  display: block;
	  width: 0.8rem;
	  height: 0.4rem;
  
	  &::before {
		position: absolute;
		content: "";
		border-color: transparent;
		border-style: solid;
	  }
	}
  }
  
  .bs-tooltip-top,
  .bs-tooltip-auto[data-popper-placement^="top"] {
	padding: 0.4rem 0;
  }
  
  .bs-tooltip-top .tooltip-arrow,
  .bs-tooltip-auto[data-popper-placement^="top"] .tooltip-arrow {
	inset-block-end: 0;
  }
  
  .bs-tooltip-top .tooltip-arrow::before,
  .bs-tooltip-auto[data-popper-placement^="top"] .tooltip-arrow::before {
	inset-block-start: 0;
	border-width: 0.4rem 0.4rem 0;
	border-block-start-color: $fixed-black;
  }
  
  .bs-tooltip-end .tooltip-arrow,
  .bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow {
	width: 0.4rem;
	height: 0.8rem;
  }
  
  .bs-tooltip-end .tooltip-arrow::before,
  .bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow::before {
	inset-inline-end: 0;
	border-block-start-width: 0.4rem;
	border-inline-end-width: 0.4rem;
	border-block-end-width: 0.4rem;
	border-inline-start-width: 0px;
	border-inline-end-color: $fixed-black;
  }
  
  .bs-tooltip-bottom,
  .bs-tooltip-auto[data-popper-placement^="bottom"] {
	padding: 0.4rem 0;
  }
  
  .bs-tooltip-bottom .tooltip-arrow,
  .bs-tooltip-auto[data-popper-placement^="bottom"] .tooltip-arrow {
	inset-block-start: 0;
  }
  
  .bs-tooltip-bottom .tooltip-arrow::before,
  .bs-tooltip-auto[data-popper-placement^="bottom"] .tooltip-arrow::before {
	inset-block-end: 0;
	border-width: 0 0.4rem 0.4rem;
	border-block-end-color: $fixed-black;
  }
  
  .bs-tooltip-start .tooltip-arrow,
  .bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow {
	width: 0.4rem;
	height: 0.8rem;
  }
  
  .bs-tooltip-start .tooltip-arrow::before,
  .bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow::before {
	inset-inline-start: 0;
	border-block-start-width: 0.4rem;
	border-inline-end-width: 0;
	border-block-end-width: 0.4rem;
	border-inline-start-width: 0.4rem;
	border-inline-start-color: $fixed-black;
  }
  
  .tooltip-inner {
	max-width: 200px;
	padding: 0.25rem 0.5rem;
	color: $fixed-white;
	text-align: center;
	background-color: $fixed-black;
	border-radius: 3px;
  }
  
  .tooltip-static-demo {
	text-align: center;
	background-color: $background;
	padding: 20px;
  
	.tooltip {
	  z-index: 0;
	  opacity: 1;
	  position: relative;
	  display: inline-block;
	  margin: 0 10px;
	}
  
	.bs-tooltip-top .tooltip-arrow,
	.bs-tooltip-auto[data-popper-placement^="top"] .tooltip-arrow,
	.bs-tooltip-bottom .tooltip-arrow,
	.bs-tooltip-auto[data-popper-placement^="bottom"] {
	  inset-inline-start: 50%;
	  margin-inline-start: -2px;
	}
  
	.bs-tooltip-start,
	.bs-tooltip-auto[data-popper-placement^="left"],
	.bs-tooltip-end,
	.bs-tooltip-auto[data-popper-placement^="right"] {
	  margin-block-start: 5px;
	}
  
	.tooltip-warning.bs-tooltip-start .tooltip-arrow,
	.bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow,
	.bs-tooltip-end .tooltip-arrow,
	.bs-tooltip-auto[data-popper-placement^="right"] .tooltip-arrow {
	  inset-block-start: 50%;
	  margin-block-start: -6px;
	}
  
	.bs-tooltip-start .tooltip-arrow,
	.bs-tooltip-auto[data-popper-placement^="left"] .tooltip-arrow,
	.bs-tooltip-end .tooltip-arrow,
	.bs-tooltip-auto[data-popper-placement^="right"] .tooltip-arrow {
	  inset-block-start: 50%;
	  margin-block-start: -6px;
	}
  }
  

  