[data-menu-style="color"] {
    .app-sidebar {
        --menu-bg: #{$primary};
        --white: #{$primary};
        --border: rgba(255, 255, 255, 0.1);
        --color: rgba(255, 255, 255, 0.6);
        // --background: rgba(255, 255, 255, 0.05);
        .sidetab-menu {
            .tab-menu-heading {
              .nav-tabs {
                .nav-item {
                  .nav-link {
                    color: rgba(255, 255, 255, 0.5);
                    p:hover {
                        color: #fff;
                    }
                    &.active {
                        background-color: $primary;
                        color: #fff;
                        p {
                            color: #fff;
                        }
                    }
                    p {
                        color: rgba(255, 255, 255, 0.5);
                    }
                  }
                }
              } 
            }
          }
    }

    .app-sidebar__header {
        background: #{$primary};
    }

    .side-menu__item {
        &.active, &:hover, &:focus {
            color: #fff !important;

            .side-menu__icon {
                // background-color: rgba(255, 255, 255, 0.3);
                border-color: rgba(255, 255, 255, 0.1);
                color: #fff;
            }
        }
    }

    .slide-item, .sub-side-menu__item, .sub-slide-item2 {
        &:hover, &.active {
            color: #fff;
        }
    }
    
    .responsive-logo .main-logo  .desktop-logo-dark{
        display: none;

        &.desktop-logo {
            display: none;
        }
    }

    .desktop-logo {
        display: block;
    }
    
    .mobile-logo, .desktop-logo-dark {
        display: none;
    }

    .slide-right, .slide-left {
        svg {
            fill: #fff;
            color: #fff;
        }
    }

    &[data-vertical-style="hover"],
    &[data-vertical-style="hover1"] {
        @media (min-width: 992px) {
            .app.show-sidenav .app-sidebar__header {

                .desktop-logo {
                    display: none !important;
                }

                .mobile-logo {
                    display: block !important;
                }

                .mobile-logo-dark {
                    display: none !important;
                }
            }
        }
    }

    &[data-vertical-style="doublemenu"],
    &[data-vertical-style="doublemenu-tabs"] {
        @media (min-width: 992px) {
           .app-sidebar__header {

                .desktop-logo {
                    display: none !important;
                }

                .mobile-logo {
                    display: block !important;
                }

                .mobile-logo-dark {
                    display: none !important;
                }
            }
        }
    }

    .side-menu__icon {
        border-color: #{$border};
    }

    @media (min-width: 992px) {
        .sidebar-mini.sidenav-toggled {
            .mobile-logo {
                display: block;
      
                &.mobile-logo-dark {
                display: none;
                }
            }
      
            &.show-sidenav {
                .desktop-logo {
                    display: block;
      
                    &.desktop-logo-dark {
                        display: none;
                    }
                }
      
                .mobile-logo {
                    display: none;
                }
            }
        }
    }

    .app-sidebar__user {
        color: #fff;
    }

    .ps__rail-y.ps--clicking .ps__thumb-y {
        background-color: rgba($color: #fff, $alpha: 0.3);
    }

    .ps .ps__rail-y.ps--clicking {
        background-color: transparent;
    }

    .ps .ps__rail-y {
        &:hover, &:focus {
            background-color: transparent;
        }
    }

    .ps__thumb-y {
        background-color: transparent;
    }

    @media (min-width: 992px) {
        &[data-vertical-style=hover1],
        &[data-vertical-style=doublemenu],
        &[data-vertical-style=doublemenu-tabs] {
            .app .side-menu__label1 a {
                color: #fff !important;
            }
        }
        &[data-vertical-style="doublemenu-tabs"] {
            .sidetab-menu {
                --primary-bg-color: rgba(255, 255, 255, 0.2);
                --muted: rgba(255, 255, 255, 0.5);
                --white: transparent;
                --gray-100: rgba(255, 255, 255, 0.2);
                --gray-200: transparent;
                --gray-300: rgba(255, 255, 255, 0.2);
                --gray-600: #fff;
                --gray-800: #fff;
                --color: #fff;
                --form-border: rgba(255, 255, 255, 0.1);
            }
            .slide-item, .sub-side-menu__item, .sub-slide-item2 {
                --color: rgba(255, 255, 255, 0.6);
            }
        } 
    }
}